#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long evenSum = 0, oddSum = 0;
    for (int i = 0; i < n; i++) {
        long long val;
        scanf("%lld", &val);
        if (val % 2 == 0) {
            evenSum += val;
        } else {
            oddSum += val;
        }
    }

    long long diff = llabs(evenSum - oddSum);
    printf("%lld\n", diff);
    return 0;
}

#include <stdio.h>
#include <string.h>

// Write your solution here
int main() {
    char s[300];
    if (scanf("%s", s) != 1) return 0;
    int len = strlen(s);
    int count = 0;

    for (int i = 0; i < len; i++) {
        // Odd length palindromes
        int l = i - 1, r = i + 1;
        while (l >= 0 && r < len && s[l] == s[r]) {
            count++;
            l--;
            r++;
        }
        // Even length palindromes
        l = i; r = i + 1;
        while (l >= 0 && r < len && s[l] == s[r]) {
            count++;
            l--;
            r++;
        }
    }

    printf("%d\n", count);
    return 0;
}

#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int mat[55][55];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &mat[i][j]);
        }
    }

    int layers = (n + 1) / 2;
    for (int l = 0; l < layers; l++) {
        int maxVal = -1000000;
        int r1 = l, c1 = l, r2 = n - 1 - l, c2 = n - 1 - l;

        for (int c = c1; c <= c2; c++) {
            if (mat[r1][c] > maxVal) maxVal = mat[r1][c];
            if (mat[r2][c] > maxVal) maxVal = mat[r2][c];
        }
        for (int r = r1; r <= r2; r++) {
            if (mat[r][c1] > maxVal) maxVal = mat[r][c1];
            if (mat[r][c2] > maxVal) maxVal = mat[r][c2];
        }
        if (l > 0) printf(" ");
        printf("%d", maxVal);
    }
    printf("\n");
    return 0;
}
